-- rotas do Yuri, 16/11/2026 (gerado por seed.py)
on conflict (codigo) do update set nome = excluded.nome, ordem = excluded.ordem, partida = excluded.partida, partida_lat = excluded.partida_lat, partida_lng = excluded.partida_lng, chegada = excluded.chegada, chegada_lat = excluded.chegada_lat, chegada_lng = excluded.chegada_lng, observacao = excluded.observacao;
update public.contas set rota_anterior = rota where rota is not null and rota_anterior is null;
update public.contas set rota = case when public.crm_chave_cidade(cidade) = 'jaguariuna' then null else 'A planejar' end where rota is not null;
-- lojas ativas (prospecção, lead aberto ou cliente) a até 500 km de Jaguariúna e fora das rotas também ficam "A planejar"
