   and (exists (select 1 from public.prospeccoes p where p.conta_id = c.id and p.status not in ('5. Sem interesse', '6. Fora do ICP'))
        or exists (select 1 from public.leads l where l.conta_id = c.id and l.status not in ('Perdido', 'Descartado'))
        or exists (select 1 from public.pos_venda v where v.conta_id = c.id));
alter table public.contas drop constraint if exists contas_rota_fk;
alter table public.contas add constraint contas_rota_fk foreign key (rota) references public.rotas(codigo) on update cascade on delete set null;
select public.crm_rotas_recalcular();