insert into public.rotas (codigo, nome, ordem, partida, partida_lat, partida_lng, chegada, chegada_lat, chegada_lng, observacao) values
('R1', 'Trajeto Jaguariúna → Rio Preto', 10, 'Jaguariúna, SP', -22.70374, -46.985062, 'São José do Rio Preto, SP', -20.8125851, -49.3804212, 'Jaguariúna é só a partida (exclusividade com a Western). 3 dias, ~507 km, pernoites em Mogi Guaçu, São Carlos e Rio Preto. A ordem Jaguariúna → Mogi Mirim → Mogi Guaçu → Cosmópolis → Limeira economiza ~19 km. Dia 1 sem lojas no CRM: prospectar e agendar antes.'),
('R1.1', 'Rio Preto · Mirassol, Monte Aprazível e Nhandeara', 20, 'São José do Rio Preto, SP', -20.8125851, -49.3804212, 'São José do Rio Preto, SP', -20.8125851, -49.3804212, 'Base em Rio Preto, ~175 km no dia. Mirassol também está na R1.2: visite numa só (na R1.1 sai sem km extra). Nhandeara não tem lojas no CRM: prospectar antes.'),
('R1.2', 'Rio Preto · Mirassol, Bálsamo e Tanabi', 30, 'São José do Rio Preto, SP', -20.8125851, -49.3804212, 'São José do Rio Preto, SP', -20.8125851, -49.3804212, 'Base em Rio Preto, ~93 km no dia. Bálsamo não tem lojas no CRM e Mirassol se repete na R1.1.'),
('R1.3', 'Rio Preto · Bady Bassitt, José Bonifácio e Lins', 40, 'São José do Rio Preto, SP', -20.8125851, -49.3804212, 'São José do Rio Preto, SP', -20.8125851, -49.3804212, 'Dividida em 2 dias pela regra de 3 cidades por dia: Dia 1 em Rio Preto (12 lojas no CRM) e Bady Bassitt; Dia 2 José Bonifácio e Lins (~268 km, a volta de Lins tem 129 km). Lins não tem lojas no CRM. Reservas no caminho: Ubarana e Guaiçara.'),
('R1.4', 'Volta · Olímpia e Barretos → Jaguariúna', 50, 'São José do Rio Preto, SP', -20.8125851, -49.3804212, 'Jaguariúna, SP', -22.70374, -46.985062, 'Num dia só são ~475 km estimados (~440 pela estrada) para 2 cidades, acima de ~400 km. Opção recomendada: dividir a volta em 2 dias com pernoite em Ribeirão Preto (~245 km + ~243 km).'),
('R1.5', 'Rio Preto · Nova Granada, Palestina e Frutal', 60, 'São José do Rio Preto, SP', -20.8125851, -49.3804212, 'São José do Rio Preto, SP', -20.8125851, -49.3804212, 'Base em Rio Preto, ~272 km no dia. Frutal é MG: conferir com o Financeiro o ICMS interestadual antes de passar condição. Palestina e Frutal sem lojas no CRM; Fronteira (MG, na BR-153) pode substituir Palestina.'),
('A planejar', 'Lojas fora das rotas, para planejar depois', 999, null, null, null, null, null, null, 'Etiqueta das lojas que tinham rota antiga (R1–R9 de 15/11) e não entram nas rotas novas')
